-- Foundation tables shared by every module (LLD 4.4, 4.5, 4.7, 5.3).
-- IDs are UUIDv7 generated by the application.

-- +goose Up
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Domain events written in the same transaction as the business change.
CREATE TABLE outbox (
  id           uuid PRIMARY KEY,
  topic        text NOT NULL,
  key          text NOT NULL DEFAULT '',
  payload      jsonb NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz
);
CREATE INDEX ix_outbox_unpublished ON outbox (created_at) WHERE published_at IS NULL;

-- Consumer de-duplication: each consumer handles an event once.
CREATE TABLE processed_events (
  consumer     text NOT NULL,
  event_id     uuid NOT NULL,
  processed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (consumer, event_id)
);

-- Idempotency-Key storage for order placement, reservations, payouts (24 h).
CREATE TABLE idempotency_keys (
  account_id   uuid NOT NULL,
  route        text NOT NULL,
  key          text NOT NULL,
  request_hash bytea NOT NULL,
  status_code  int,
  response     jsonb,
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (account_id, route, key)
);
CREATE INDEX ix_idempotency_created ON idempotency_keys (created_at);

-- Raw webhooks from simulators, de-duplicated by provider event id.
CREATE TABLE webhook_events (
  provider     text NOT NULL,
  event_id     text NOT NULL,
  received_at  timestamptz NOT NULL DEFAULT now(),
  payload      jsonb NOT NULL,
  processed_at timestamptz,
  PRIMARY KEY (provider, event_id)
);

-- Admin-editable business settings, versioned (FR-ADM-03).
CREATE TABLE config (
  key        text PRIMARY KEY,
  value      jsonb NOT NULL,
  version    int NOT NULL DEFAULT 1,
  updated_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE config_history (
  key        text NOT NULL,
  version    int NOT NULL,
  value      jsonb NOT NULL,
  changed_by uuid,
  changed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (key, version)
);

-- Append-only audit trail (FR-ADM-09). The app role gets INSERT/SELECT only.
CREATE TABLE audit_log (
  id             uuid PRIMARY KEY,
  actor_id       uuid,
  acting_as_role text,
  action         text NOT NULL,
  target_type    text NOT NULL,
  target_id      text NOT NULL,
  before         jsonb,
  after          jsonb,
  ip             inet,
  at             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_audit_target ON audit_log (target_type, target_id);

-- +goose Down
DROP TABLE audit_log;
DROP TABLE config_history;
DROP TABLE config;
DROP TABLE webhook_events;
DROP TABLE idempotency_keys;
DROP TABLE processed_events;
DROP TABLE outbox;
